using PX.Data;
using PX.Data.BQL;
using PX.Objects.AR;

namespace HeritageFabrics.AR
{
    public sealed class CustomerExt : PXCacheExtension<Customer>
    {
        public static bool IsActive() => true;

        #region UsrDisablePayLink
        public abstract class usrDisablePayLink : BqlBool.Field<usrDisablePayLink> { }

        [PXDBBool]
        [PXDefault(false, PersistingCheck = PXPersistingCheck.Nothing)]
        [PXUIField(DisplayName = "Exclude from Payment Link Processing")]
        public bool? UsrDisablePayLink { get; set; }
        #endregion
    }
}

using System;
using PX.Data;
using PX.Objects.AR;
using PX.Objects.CS;

namespace HeritageFabrics.AR
{
    public class ARInvoiceEntry_PayLink_Extension : PXGraphExtension<ARInvoiceEntry>
    {
        public static bool IsActive() => true;

        protected void _(Events.RowSelected<ARInvoice> e)
        {
            if (e.Row == null) return;

            bool disablePayLink = IsPayLinkDisabledForCustomer(e.Row.CustomerID);

            if (Base.Actions.Contains("SendPaymentLink"))
            {
                Base.Actions["SendPaymentLink"].SetEnabled(!disablePayLink);
            }

            if (Base.Actions.Contains("sendPayLink"))
            {
                Base.Actions["sendPayLink"].SetEnabled(!disablePayLink);
            }
        }

        private bool IsPayLinkDisabledForCustomer(int? customerID)
        {
            if (customerID == null) return false;

            Customer customer = PXSelect<Customer,
                Where<Customer.bAccountID, Equal<Required<Customer.bAccountID>>>>
                .Select(Base, customerID);

            if (customer == null) return false;

            // Check 1: Explicit per-customer flag
            CustomerExt ext = customer.GetExtension<CustomerExt>();
            if (ext?.UsrDisablePayLink == true) return true;

            // Check 2: Terms description contains "factor"
            if (!string.IsNullOrEmpty(customer.TermsID))
            {
                Terms terms = PXSelect<Terms,
                    Where<Terms.termsID, Equal<Required<Terms.termsID>>>>
                    .Select(Base, customer.TermsID);
                if (terms?.Descr != null &&
                    terms.Descr.IndexOf("factor", StringComparison.OrdinalIgnoreCase) >= 0)
                    return true;
            }

            return false;
        }
    }
}

using PX.Data;
using PX.Data.BQL;
using PX.Objects.SO;

namespace HeritageFabrics.SO
{
    public sealed class SOOrderExt : PXCacheExtension<SOOrder>
    {
        public static bool IsActive() => true;

        #region UsrHubSpotDealId
        public abstract class usrHubSpotDealId : BqlString.Field<usrHubSpotDealId> { }

        [PXDBString(50, IsUnicode = true)]
        [PXUIField(DisplayName = "HubSpot Order ID", Visibility = PXUIVisibility.SelectorVisible)]
        public string UsrHubSpotDealId { get; set; }
        #endregion

        #region UsrWMSStatus
        public abstract class usrWMSStatus : BqlString.Field<usrWMSStatus> { }

        [PXDBString(20, IsUnicode = true)]
        [PXDefault(PersistingCheck = PXPersistingCheck.Nothing)]
        [PXUIField(DisplayName = "WMS Status")]
        [PXStringList(
            new[] { "N", "A", "P", "F", "K", "S" },
            new[] { "Not Started", "Allocated", "Picking", "Finishing", "Packed", "Shipped" }
        )]
        public string UsrWMSStatus { get; set; }
        #endregion

        #region UsrComplianceHold
        public abstract class usrComplianceHold : BqlBool.Field<usrComplianceHold> { }

        [PXDBBool]
        [PXDefault(false, PersistingCheck = PXPersistingCheck.Nothing)]
        [PXUIField(DisplayName = "Compliance Hold", Enabled = false)]
        public bool? UsrComplianceHold { get; set; }
        #endregion

        #region UsrComplianceHoldReason
        public abstract class usrComplianceHoldReason : BqlString.Field<usrComplianceHoldReason> { }

        [PXDBString(500, IsUnicode = true)]
        [PXUIField(DisplayName = "Compliance Hold Reason", Enabled = false)]
        public string UsrComplianceHoldReason { get; set; }
        #endregion
    }
}

using PX.Data;
using PX.Objects.SO;

namespace HeritageFabrics.SO
{
    public class SOOrderEntry_ComplianceHold : PXGraphExtension<SOOrderEntry>
    {
        public static bool IsActive() => true;

        protected void _(Events.RowSelected<SOOrder> e)
        {
            if (e.Row == null) return;
            SOOrderExt ext = e.Row.GetExtension<SOOrderExt>();
            bool held = ext?.UsrComplianceHold == true;

            Base.Actions["CreateShipmentIssue"]?.SetEnabled(!held);
            AcknowledgeComplianceHold.SetVisible(held);
            AcknowledgeComplianceHold.SetEnabled(held);

            if (held)
            {
                e.Cache.RaiseExceptionHandling<SOOrderExt.usrComplianceHold>(
                    e.Row, true,
                    new PXSetPropertyException(
                        "This order is on compliance hold. Review and acknowledge requirements before shipping.",
                        PXErrorLevel.Warning));
            }
        }

        public PXAction<SOOrder> AcknowledgeComplianceHold;

        [PXButton(CommitChanges = true)]
        [PXUIField(DisplayName = "Acknowledge Compliance", MapEnableRights = PXCacheRights.Update)]
        protected void acknowledgeComplianceHold()
        {
            SOOrder order = Base.Document.Current;
            if (order == null) return;

            SOOrderExt ext = order.GetExtension<SOOrderExt>();
            if (ext?.UsrComplianceHold != true) return;

            Base.Document.Cache.SetValueExt<SOOrderExt.usrComplianceHold>(order, false);
            Base.Document.Cache.SetValueExt<SOOrderExt.usrComplianceHoldReason>(order, null);
            Base.Document.Update(order);
            Base.Actions.PressSave();
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using PX.Data;
using PX.Data.BQL;
using PX.Objects.PO;

namespace HeritageFabrics.PO
{
    public class POReceiptEntry_Extension : PXGraphExtension<POReceiptEntry>
    {
        public static bool IsActive() => true;

        public PXAction<POReceipt> PrintPurchaseReceiptLabels;
        [PXButton(CommitChanges = true)]
        [PXUIField(DisplayName = "Print Purchase Receipt Labels", MapEnableRights = PXCacheRights.Select)]
        protected virtual IEnumerable printPurchaseReceiptLabels(PXAdapter adapter)
        {
            PXReportRequiredException ex = null;
            var row = Base.Caches[typeof(POReceipt)].Current as POReceipt;
            if (row != null)
            {
                var parameters = new Dictionary<string, string>();
                parameters["ReceiptType"] = row.ReceiptType?.ToString();
                parameters["ReceiptNbr"] = row.ReceiptNbr?.ToString();
                ex = new PXReportRequiredException(parameters, "PO646901");
            }
            if (ex != null) throw ex;
            return adapter.Get();
        }
    }
}

using System;
using System.IO;
using System.Net;
using System.Text;
using System.Threading;
using PX.Data;
using PX.Objects.SO;

namespace HeritageFabrics.SO
{
    /// <summary>
    /// Fires a webhook when PC/CO sales orders are created, taken off hold,
    /// or have their backorder flag cleared. The webhook triggers lot-level
    /// inventory auto-allocation in the external allocation service.
    ///
    /// Uses RowPersisted (post-commit) + ThreadPool for fire-and-forget HTTP.
    /// Failures are silently swallowed — the allocation service has its own
    /// retry/cron mechanism.
    /// </summary>
    public class SOOrderEntry_AutoAlloc_Extension : PXGraphExtension<SOOrderEntry>
    {
        public static bool IsActive() => true;

        private const string WebhookUrl =
            "https://webhook-router-production-e161.up.railway.app/webhook/acumatica/allocate-inventory";

        private static readonly string[] AllocOrderTypes = new[] { "PC", "CO" };

        #region Event Handlers

        /// <summary>
        /// After a new order is persisted (inserted), fire trigger=entry.
        /// </summary>
        protected void _(Events.RowPersisted<SOOrder> e)
        {
            if (e.TranStatus != PXTranStatus.Completed) return;
            if (e.Row == null) return;
            if (e.Operation != PXDBOperation.Insert) return;
            if (!IsAllocOrderType(e.Row.OrderType)) return;

            FireWebhook(e.Row.OrderType, e.Row.OrderNbr, "entry");
        }

        /// <summary>
        /// When Hold changes to false, fire trigger=remove-hold.
        /// </summary>
        protected void _(Events.FieldUpdated<SOOrder, SOOrder.hold> e)
        {
            if (e.Row == null) return;
            bool? oldVal = (bool?)e.OldValue;
            bool? newVal = e.Row.Hold;

            // Only fire when transitioning from held (true) to not-held (false)
            if (oldVal == true && newVal == false && IsAllocOrderType(e.Row.OrderType))
            {
                // Defer until after persist completes
                Base.RowPersisted.AddHandler<SOOrder>((cache, args) =>
                {
                    if (args.TranStatus == PXTranStatus.Completed &&
                        args.Operation == PXDBOperation.Update)
                    {
                        FireWebhook(e.Row.OrderType, e.Row.OrderNbr, "remove-hold");
                    }
                });
            }
        }

        /// <summary>
        /// When BackOrder (IsBackOrder? or similar) changes to false,
        /// fire trigger=remove-backorder.
        /// SOOrder.backOrdered is the standard field for back-order status.
        /// </summary>
        protected void _(Events.FieldUpdated<SOOrder, SOOrder.backOrdered> e)
        {
            if (e.Row == null) return;
            bool? oldVal = (bool?)e.OldValue;
            bool? newVal = e.Row.BackOrdered;

            if (oldVal == true && newVal == false && IsAllocOrderType(e.Row.OrderType))
            {
                Base.RowPersisted.AddHandler<SOOrder>((cache, args) =>
                {
                    if (args.TranStatus == PXTranStatus.Completed &&
                        args.Operation == PXDBOperation.Update)
                    {
                        FireWebhook(e.Row.OrderType, e.Row.OrderNbr, "remove-backorder");
                    }
                });
            }
        }

        #endregion

        #region Helpers

        private static bool IsAllocOrderType(string orderType)
        {
            if (string.IsNullOrEmpty(orderType)) return false;
            foreach (string t in AllocOrderTypes)
            {
                if (string.Equals(t, orderType, StringComparison.OrdinalIgnoreCase))
                    return true;
            }
            return false;
        }

        /// <summary>
        /// Fire-and-forget HTTP POST to the allocation webhook.
        /// Runs on a ThreadPool thread so it never blocks the Acumatica transaction.
        /// Failures are logged via PXTrace but never thrown.
        /// </summary>
        private static void FireWebhook(string orderType, string orderNbr, string trigger)
        {
            string json = string.Format(
                "{{\"OrderType\":\"{0}\",\"OrderNbr\":\"{1}\",\"Trigger\":\"{2}\"}}",
                EscapeJson(orderType), EscapeJson(orderNbr), EscapeJson(trigger));

            ThreadPool.QueueUserWorkItem((_) =>
            {
                try
                {
                    HttpWebRequest req = (HttpWebRequest)WebRequest.Create(WebhookUrl);
                    req.Method = "POST";
                    req.ContentType = "application/json";
                    req.Timeout = 10000; // 10s timeout

                    byte[] data = Encoding.UTF8.GetBytes(json);
                    req.ContentLength = data.Length;
                    using (Stream stream = req.GetRequestStream())
                    {
                        stream.Write(data, 0, data.Length);
                    }
                    using (HttpWebResponse resp = (HttpWebResponse)req.GetResponse())
                    {
                        PXTrace.WriteInformation(
                            $"[AutoAlloc] Webhook fired: {trigger} {orderType}-{orderNbr} → HTTP {(int)resp.StatusCode}");
                    }
                }
                catch (Exception ex)
                {
                    PXTrace.WriteError(
                        $"[AutoAlloc] Webhook failed: {trigger} {orderType}-{orderNbr} → {ex.Message}");
                }
            });
        }

        private static string EscapeJson(string s)
        {
            if (s == null) return "";
            return s.Replace("\\", "\\\\").Replace("\"", "\\\"");
        }

        #endregion
    }
}
